// Package forgereach answers one question for forge's CI gates: can this diff
// change what a consumer of forge sees?
//
// A consumer is a project generated by forge (reliant, control-plane). It sees
// forge in two ways:
//
//   - the Go packages under pkg/ it imports (and the module-internal packages
//     those import), so a change there can break its build;
//   - the code `forge generate` writes into it, so a change to the templates or
//     the generators can break the build after the consumer regenerates.
//
// Everything else in the module (the CLI's commands, the linters, the docs)
// never reaches a consumer's build, and a gate that ran on it would spend its
// time on diffs that cannot matter.
//
//forge:exclude-contract: pure functions over a git diff and go list output, no collaborator to substitute
package forgereach

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path"
	"sort"
	"strings"

	"golang.org/x/mod/modfile"

	"github.com/reliant-labs/forge/internal/goexec"
)

// Git runs git in dir and returns stdout.
func Git(dir string, args ...string) ([]byte, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git %s: %w\n%s", strings.Join(args, " "), err, strings.TrimSpace(stderr.String()))
	}
	return out, nil
}

// GoList runs `go list args...` in dir with the workspace off and returns stdout.
func GoList(dir string, args ...string) ([]byte, error) {
	cmd := exec.Command("go", append([]string{"list"}, args...)...)
	cmd.Dir = dir
	cmd.Env = goexec.Env("GOWORK=off")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("go list %s (in %s): %w\n%s", strings.Join(args, " "), dir, err, strings.TrimSpace(stderr.String()))
	}
	return out, nil
}

// ChangedFiles lists the files that differ from base in the checkout at dir —
// uncommitted and untracked ones included — as slash paths relative to dir,
// sorted.
func ChangedFiles(dir, base string) ([]string, error) {
	tracked, err := Git(dir, "diff", "--name-only", base, "--")
	if err != nil {
		return nil, err
	}
	untracked, err := Git(dir, "ls-files", "--others", "--exclude-standard")
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	var out []string
	for _, blob := range [][]byte{tracked, untracked} {
		for _, f := range strings.Split(string(blob), "\n") {
			// A trailing slash is a nested repository (a consumer checked
			// out beside the sources), not a file of this module.
			if f = strings.TrimSpace(f); f != "" && !strings.HasSuffix(f, "/") && !seen[f] {
				seen[f] = true
				out = append(out, f)
			}
		}
	}
	sort.Strings(out)
	return out, nil
}

// ExportRev writes the tree of rev into dst (git archive; no repository state).
func ExportRev(dir, rev, dst string) error {
	arch := exec.Command("git", "-C", dir, "archive", rev)
	tar := exec.Command("tar", "-x", "-C", dst)
	pipe, err := arch.StdoutPipe()
	if err != nil {
		return err
	}
	tar.Stdin = pipe
	var aerr, terr bytes.Buffer
	arch.Stderr, tar.Stderr = &aerr, &terr
	if err := tar.Start(); err != nil {
		return err
	}
	if err := arch.Run(); err != nil {
		_ = tar.Process.Kill()
		_ = tar.Wait()
		return fmt.Errorf("git archive %s: %w\n%s", rev, err, strings.TrimSpace(aerr.String()))
	}
	if err := tar.Wait(); err != nil {
		return fmt.Errorf("extract %s: %w\n%s", rev, err, strings.TrimSpace(terr.String()))
	}
	return nil
}

// Reach is what a diff can change for a consumer.
type Reach struct {
	// Module is the forge module path.
	Module string
	// All is true when the module's dependency set changed (see depsChanged):
	// any consumer package that imports forge may be affected.
	All bool
	// Packages are the import paths of the changed Go packages a consumer can
	// import, directly (pkg/...) or through a package of pkg/, sorted.
	Packages []string
	// Generated are the changed files whose output lands in a consumer's tree
	// when it runs `forge generate`: templates, generators, scaffolding.
	Generated []string
}

// API reports whether the diff can change the Go API consumers compile against.
func (r Reach) API() bool { return r.All || len(r.Packages) > 0 }

// Any reports whether the diff can reach a consumer at all.
func (r Reach) Any() bool { return r.API() || len(r.Generated) > 0 }

// Summary is one line naming why a diff reaches consumers.
func (r Reach) Summary() string {
	var parts []string
	if r.All {
		parts = append(parts, "the module's dependencies changed")
	}
	if len(r.Packages) > 0 {
		parts = append(parts, fmt.Sprintf("%d package(s) a consumer imports", len(r.Packages)))
	}
	if len(r.Generated) > 0 {
		parts = append(parts, fmt.Sprintf("%d file(s) that change generated code", len(r.Generated)))
	}
	if len(parts) == 0 {
		return "nothing a consumer sees"
	}
	return strings.Join(parts, ", ")
}

// generatedPrefixes are the trees whose edits change what `forge generate`
// writes into a consumer: the scaffold, the templates, the generators and
// generate, which the e2e suite (e2e-suite.yml) exercises.
var generatedPrefixes = []string{
	"internal/templates/", "internal/codegen/", "internal/generator/",
	"internal/cli/scaffold", "internal/cli/generate",
}

func isNoise(f string) bool {
	return strings.HasSuffix(f, "_test.go") || strings.Contains("/"+f, "/testdata/")
}

func isGenerated(f string) bool {
	if isNoise(f) {
		return false
	}
	// Skill markdown is read by agents, never written into a consumer's Go tree.
	if strings.HasPrefix(f, "internal/templates/project/skills/") {
		return false
	}
	for _, p := range generatedPrefixes {
		if strings.HasPrefix(f, p) {
			return true
		}
	}
	return false
}

// depsChanged reports whether go.mod or go.sum changed in a way that can alter
// which versions of anything a consumer builds with. A go.mod edit that leaves
// every require and replace as it was (promoting a module from indirect to
// direct, a comment, a reordering) changes no build, so it is not a reason to
// build the consumers. A go.sum change with go.mod untouched is one.
func depsChanged(root, base string, changed []string) bool {
	var mod, sum bool
	for _, f := range changed {
		mod = mod || f == "go.mod"
		sum = sum || f == "go.sum"
	}
	if !mod && !sum {
		return false
	}
	if !mod {
		return true
	}
	oldb, err := Git(root, "show", base+":go.mod")
	if err != nil {
		return true
	}
	newb, err := os.ReadFile(root + "/go.mod")
	if err != nil {
		return true
	}
	a, b := requirements(oldb), requirements(newb)
	if a == nil || b == nil || len(a) != len(b) {
		return true
	}
	for k, v := range a {
		if b[k] != v {
			return true
		}
	}
	return false
}

// requirements is the set of "kind path" -> version a go.mod pins: its
// requires, replaces, and go/toolchain lines. Nil when it does not parse.
func requirements(data []byte) map[string]string {
	f, err := modfile.Parse("go.mod", data, nil)
	if err != nil {
		return nil
	}
	m := map[string]string{}
	for _, r := range f.Require {
		m["require "+r.Mod.Path] = r.Mod.Version
	}
	for _, r := range f.Replace {
		m["replace "+r.Old.Path+"@"+r.Old.Version] = r.New.Path + "@" + r.New.Version
	}
	if f.Go != nil {
		m["go"] = f.Go.Version
	}
	if f.Toolchain != nil {
		m["toolchain"] = f.Toolchain.Name
	}
	return m
}

// Compute maps the changed files (relative to the forge module at root, as
// differing from base) onto what a consumer can see.
func Compute(root, base string, changed []string) (Reach, error) {
	modOut, err := GoList(root, "-m")
	if err != nil {
		return Reach{}, err
	}
	mod := strings.TrimSpace(string(modOut))
	r := Reach{Module: mod, All: depsChanged(root, base, changed)}

	// Only load the package graph when a changed file could matter.
	var goFiles []string
	for _, f := range changed {
		switch {
		case isGenerated(f):
			r.Generated = append(r.Generated, f)
		}
		if strings.HasSuffix(f, ".go") && !isNoise(f) || strings.HasSuffix(f, ".proto") {
			goFiles = append(goFiles, f)
		}
	}
	if len(goFiles) == 0 {
		return r, nil
	}

	all, err := GoList(root, "-f", "{{.ImportPath}}", "./...")
	if err != nil {
		return Reach{}, err
	}
	dirOf := map[string]string{} // relative dir -> import path
	for _, ip := range strings.Fields(string(all)) {
		if d, ok := strings.CutPrefix(ip, mod+"/"); ok {
			dirOf[d] = ip
		} else if ip == mod {
			dirOf["."] = ip
		}
	}
	deps, err := GoList(root, "-deps", "-f", "{{.ImportPath}}", "./pkg/...")
	if err != nil {
		return Reach{}, err
	}
	visible := map[string]bool{}
	for _, ip := range strings.Fields(string(deps)) {
		if ip == mod || strings.HasPrefix(ip, mod+"/") {
			visible[ip] = true
		}
	}

	seen := map[string]bool{}
	add := func(ip string) {
		if !seen[ip] {
			seen[ip] = true
			r.Packages = append(r.Packages, ip)
		}
	}
	for _, f := range goFiles {
		found := false
		for d := path.Dir(f); ; d = path.Dir(d) {
			if ip, ok := dirOf[d]; ok {
				if visible[ip] {
					add(ip)
				}
				found = true
				break
			}
			if d == "." || d == "/" || d == "" {
				break
			}
		}
		// A file under pkg/ with no package left in the tree: the package was
		// deleted, which every importer sees.
		if !found && strings.HasPrefix(f, "pkg/") {
			add(mod + "/" + path.Dir(f))
		}
	}
	sort.Strings(r.Packages)
	return r, nil
}
